import {MAPS} from './maps.js';
const $=id=>document.getElementById(id);
export function initLanUI(client,getProfile){
 let info=null,error='',localAvailable=true;try{$('lan-name').value=localStorage.getItem('fusionfall-lan-name')||''}catch{}
 for(const map of MAPS){const option=document.createElement('option');option.value=map.id;option.textContent=map.name+' / '+map.title;$('lan-map').appendChild(option)}
 function status(message){error=message;$('lan-status').textContent=message}
 function availability(available){localAvailable=available;for(const selector of ['.lan-fields','.lan-share','.lan-label','.lan-actions','#lan-roster'])document.querySelector('#lan-panel '+selector)?.classList.toggle('hidden',!available);if(!available){$('lan-edit').classList.add('hidden');$('lan-leave').classList.add('hidden');$('lan-close').classList.remove('hidden');status('This hosted edition supports solo play. For LAN co-op, open the local network link provided by the computer hosting the game.')}}
 function render(lobby=client.lobby||info?.lobby){if(!lobby)return;const joined=client.joined,host=client.isHost,players=lobby.players||[];$('lan-roster').replaceChildren();for(let i=0;i<4;i++){const player=players[i],row=document.createElement('li'),name=document.createElement('strong'),detail=document.createElement('span');if(player){name.textContent=player.profile.name+(player.id===client.id?' (you)':'');detail.textContent=!player.connected?'Reconnecting':player.id===lobby.hostId?'HOST':'TEAMMATE'}else{name.textContent='Open slot';detail.textContent='Waiting for a player';row.className='empty-slot'}row.append(name,detail);$('lan-roster').appendChild(row)}$('lan-map').value=lobby.map;$('lan-map').disabled=!joined||!host||lobby.phase==='playing';$('lan-create').classList.toggle('hidden',joined);$('lan-join').classList.toggle('hidden',joined&&client.connected);$('lan-create').disabled=players.length>0;$('lan-join').disabled=!players.length;$('lan-join').textContent=joined?'RECONNECT':'JOIN PARTY';$('lan-start').classList.toggle('hidden',!joined||!host||lobby.phase==='playing'||!client.connected);$('lan-start').textContent=lobby.phase==='result'?'START NEW RUN':'DEPLOY PARTY';$('lan-leave').classList.toggle('hidden',!joined);$('lan-edit').classList.toggle('hidden',!joined||lobby.phase==='playing');$('lan-close').classList.toggle('hidden',joined&&lobby.phase==='playing'&&!client.running);$('lan-name').disabled=joined;if(!error)$('lan-status').textContent=joined?(lobby.phase==='playing'?'Match in progress. Late joins are welcome.':host?'Choose the map, then deploy when your party is ready.':'Your host will start the match.'):'Host a party or join the party on this server.';}
 async function refresh(){try{const response=await fetch('/api/lan',{cache:'no-store'});if(response.status===404){availability(false);return}if(!response.ok)throw Error('LAN server unavailable. Start the game with npm start on the host.');info=await response.json();availability(true);if(info.protocol!==1)throw Error('Game versions differ. Refresh this page.');const current=location.hostname!=='localhost'&&location.hostname!=='127.0.0.1'?location.origin:null,preferred=info.addresses.find(a=>/ethernet|wi-fi/i.test(a.name))||info.addresses[0];$('lan-address').value=(current||preferred?.url||location.origin)+'/?lan=1';error='';render(client.joined?client.lobby:info.lobby)}catch(e){status(e.message)}}
 async function open(){error='';$('lan-panel').classList.remove('hidden');await refresh();$(localAvailable?'lan-name':'lan-close').focus()}
 function close(){$('lan-panel').classList.add('hidden');$('lan-button').focus()}
 async function connect(mode){const buttons=[$('lan-create'),$('lan-join')];buttons.forEach(b=>b.disabled=true);try{const name=$('lan-name').value.trim()||'Operative';try{localStorage.setItem('fusionfall-lan-name',name)}catch{}const profile={...getProfile(),name};status('Connecting...');await client.connect(mode,profile,getProfile().map);error='';render();}catch(e){status(e.message)}finally{render();}}
 $('lan-button').onclick=open;$('lan-refresh').onclick=refresh;$('lan-close').onclick=close;$('lan-create').onclick=()=>connect('create');$('lan-join').onclick=()=>connect('join');$('lan-start').onclick=()=>{client.updateProfile({...getProfile(),name:$('lan-name').value.trim()||'Operative'});client.start()};$('lan-map').onchange=()=>client.chooseMap($('lan-map').value);$('lan-edit').onclick=close;$('lan-copy').onclick=async()=>{try{await navigator.clipboard.writeText($('lan-address').value);status('LAN address copied.')}catch{$('lan-address').select();status('Address selected. Press Ctrl+C to copy.')}};
 return {open,close,refresh,render,status,get name(){return $('lan-name').value.trim()||'Operative'}};
}
